const messages = $input.all();

if (messages.length === 0) {
  return [
    {
      json: {
        decision: "NONE"
      }
    }
  ];
}

const message = messages[0].json;

const text = [
  message.text,
  message.snippet,
  message.body,
  message.payload?.body?.data
]
  .filter(Boolean)
  .join("\n")
  .toUpperCase();

let decision = "NONE";

if (/\bAPPROVE\b/.test(text)) {
  decision = "APPROVE";
} else if (/\bREJECT\b/.test(text)) {
  decision = "REJECT";
}

return [
  {
    json: {
      decision
    }
  }
];

