const messages = $input.all();

if (messages.length === 0) {
  return [
    {
      json: {
        selection: "NONE"
      }
    }
  ];
}

const message = messages[0].json;

// Gmail commonly provides the actual reply in text/plain.
// Check all likely fields.
const text = [
  message.text,
  message.snippet,
  message.body,
  message.payload?.body?.data
]
  .filter(Boolean)
  .join("\n");

// Look specifically for a standalone 1, 2, or 3.
// The first standalone number is treated as the selection.
const matches = text.match(/\b[123]\b/g);

let selection = "NONE";

if (matches && matches.length > 0) {
  selection = matches[0];
}

return [
  {
    json: {
      selection
    }
  }
];

return [
  {
    json: {
      status: "INVALID",
      message: "Approval response must be exactly 1, 2, or 3."
    }
  }
];
